  "추가": "添加",
  "연결 시작 실패. Supabase 프로젝트에서 이 로그인 방식과 계정 연결(manual linking) 활성화 확인 필요": "无法开始关联。请确认 Supabase 项目已启用此登录方式和账号关联（manual linking）",
  "마지막 로그인 수단은 연결 해제 불가": "无法解除最后一种登录方式",
  "연결 해제 실패": "解除关联失败",
  "복사됨": "已复制",
  "복사": "复制",
  "로그인 수단": "登录方式",
  "이메일·비밀번호": "邮箱和密码",
  "연결 해제": "解除关联",
  "연결하기": "关联",
  "어떤 수단으로 로그인해도 같은 계정으로 연결. 다른 기기·로그인 방식을 함께 쓰려면 미리 연결": "无论用哪种方式登录，都会进入同一个账号。想在其他设备或用其他方式登录，请提前关联",
  "계정 탈퇴": "注销账号",
  "확인을 위해 \"{0}\" 입력": "为确认，请输入“{0}”",
  "백의 첫 수. e4는 개방적·공격적, d4는 전략적·폐쇄적": "白方首着。e4 开放且进攻性强，d4 战略性强且偏封闭",
  "이탈리안 게임의 갈림길. 흑 …Bc5(지우코 피아노, 조용한 전략전) 또는 …Nf6(투 나이츠, 날카로운 전술전). 채택률 비슷": "意大利开局的分岔点。黑方走 …Bc5（朱奥科·皮亚诺，平稳的战略对攻）或 …Nf6（双马防御，尖锐的战术对攻）。采用率相近",
  "4.Ng5는 f7 직접 위협. 평가를 지키는 수는 사실상 4...d5뿐": "4.Ng5 直接威胁 f7。能保住评价的着法实际上只有 4...d5",
  "트랙슬러 카운터어택. f7을 내주고 f2를 맞받는 함정 수": "特拉克斯勒反击。放弃 f7 而反攻 f2 的陷阱着法",
  "백의 첫 수. 게임 전체 성격(개방/폐쇄, 전술/전략)을 정하는 최상위 분기": "白方首着。决定整盘棋性格（开放/封闭、战术/战略）的最高层分支",
  "흑의 선택지: 1...e5(오픈 게임), c5(시칠리안), e6(프렌치), c6(카로칸)": "黑方的选择：1...e5（开放性开局）· c5（西西里防御）· e6（法兰西防御）· c6（卡罗-卡恩防御）",
  "흑 e5 방어: 2...Nc6(정통), Nf6(페트로프), d6(필리도르)": "黑方保护 e5:2...Nc6（正统）· Nf6（彼得罗夫防御）· d6（菲利道尔防御）",
  "백의 공격 플랜: 3.Bb5(루이 로페즈, 구조적 압박) vs 3.Bc4(이탈리안, 빠른 f7 공략)": "白方进攻计划：3.Bb5（西班牙开局/鲁伊·洛佩斯，结构性施压）对 3.Bc4（意大利开局，快速进攻 f7）",
  "이탈리안의 성격: 3...Bc5(지우코 피아노, 전략전) vs 3...Nf6(투 나이츠, 전술전)": "意大利开局的性格：3...Bc5（朱奥科·皮亚诺，战略性）对 3...Nf6（双马防御，战术性）",
  "프라이드 리버: f7 위협에 4...d5만 사실상 유일한 정수": "煎肝攻击：面对 f7 的威胁，实际上只有 4...d5 是唯一正解",
  "루이 로페즈 핵심: 3...a6(모펀 메인) vs 3...Nf6(베를린 디펜스)": "西班牙开局要点：3...a6（莫菲主线）对 3...Nf6（柏林防御）",
  "안티-시칠리안: 2.Nf3(오픈 시칠리안) vs 2.Nc3 / c3 / Bc4(폐쇄·알라핀 등)": "反西西里：2.Nf3（开放西西里）对 2.Nc3 / c3 / Bc4（封闭体系、阿拉平等）",
  "오픈 시칠리안: 2...d6(나이도르프/드래곤), Nc6(스벤니/클래식), e6(타이마노프/카안)": "开放西西里：2...d6（纳依多夫/龙式）· Nc6（斯维什尼科夫/古典）· e6（泰曼诺夫/卡恩）",
  "프렌치 구조: 3.Nc3, Nd2(타라쉬), e5(어드밴스), exd5(익스체인지)로 폰 구조가 갈림": "法兰西防御的结构：3.Nc3, Nd2（塔拉什）· e5（推进）· exd5（兑换）后兵型分流",
  "카로칸 구조: 3.Nc3/Nd2(클래시컬), e5(어드밴스), exd5(익스체인지), f3(핀란드)": "卡罗-卡恩防御的结构：3.Nc3/Nd2（古典）· e5（推进）· exd5（兑换）· f3（芬兰）",
  "흑의 응수: 1...d5(정통 폐쇄) vs 1...Nf6(인디언, 초현대적 중앙 양보)": "黑方应对：1...d5（正统封闭）对 1...Nf6（印度防御，超现代式地让出中心）",
  "퀸스 갬빗: 2...e6(QGD), c6(슬라브), dxc4(QGA)": "后翼弃兵：2...e6(QGD)· c6（斯拉夫）· dxc4(QGA)",
  "인디언 디펜스: 2...e6(님조/QID), g6(KID/그륀펠트), c5(베노니)": "印度防御：2...e6（尼姆佐/QID）· g6（KID/格林菲尔德）· c5（别诺尼）",
  "3...Bb4(님조-인디언, 핀) vs 3...d5(QGD 전환)": "3...Bb4（尼姆佐-印度防御，牵制）对 3...d5（转入 QGD）",
  "3...d5(그륀펠트, 중앙 반격) vs 3...Bg7→d6(킹스 인디언, 폐쇄 공격)": "3...d5（格林菲尔德，中心反击）对 3...Bg7→d6（王翼印度防御，封闭式进攻）",
  "다미아노 디펜스 응징의 핵심. 4.Qh5+ 더블 어택으로 e5 폰 회수, 흑 킹 노출": "惩罚达米亚诺防御的关键。4.Qh5+ 双重攻击夺回 e5 兵，并使黑王暴露",
  "폰지아니 오프닝. d4를 준비하며 중앙을 노리는 고전 정석": "庞齐亚尼开局。为 d4 做准备并瞄准中心的经典定式",
  "스칸디나비안 디펜스. 흑이 d5로 중앙을 바로 교환해 빠르게 전개. 백은 2.exd5 뒤 퀸/나이트 회수 라인으로 분기": "斯堪的纳维亚防御。黑方立即以 d5 兑换中心并快速出子。白方在 2.exd5 之后分为用后或用马夺回的线路",
  "이미지를 읽지 못함": "无法读取图片",
  "네트워크 오류로 이미지 인식 실패": "因网络错误，图片识别失败",
  "기물을 희생하면서도 포지션을 유리하게 이끄는, 찾기 어려운 최상의 수": "在弃子的同时把局面引向有利的、很难找到的最佳着法",
  "두지 않으면 포지션이 크게 나빠지는, 사실상 유일하게 좋은 수": "不走就会使局面大幅恶化，实际上是唯一的好着法",
  "엔진이 계산한 그 포지션의 가장 좋은 수": "引擎计算出的该局面的最佳着法",
  "최선은 아니지만 평가치 손실이 거의 없는 훌륭한 수": "虽非最佳，但几乎不损失评价值的优秀着法",
  "무난하게 좋은 수. 포지션을 크게 해치지 않음": "稳妥的好着法，不会严重损害局面",
  "더 나은 수가 있었던, 평가치 손실이 약간 있는 수": "本有更好着法、评价值略有损失的着法",
  "상대 실수로 생긴 기회를 살리지 못한 수": "没能抓住对手失误所带来机会的着法",
  "평가치를 눈에 띄게 떨어뜨려 불리해진 수": "明显拉低评价值、使局面变得不利的着法",
  "승패를 뒤집을 만큼 평가치를 크게 잃은 치명적인 실수": "评价值大幅下降、足以扭转胜负的致命失误",
  "정석(오프닝 이론)에 등록된 이론 수": "已收录在定式（开局理论）中的理论着法",
