  "/user 페이지 우상단 X 버튼을 점 3개 메뉴(신고·차단)로 교체했습니다. 좌상단에 @아이디 표시합니다.": "/user 页面右上角的 X 按钮改为三点菜单（举报·拉黑），左上角显示 @ID。",
  "신고 사유를 체크박스로 중복 선택했습니다. 개발자 모드에서 신고자·신고 대상 아이디와 신고 내용(최근 대화 포함) 열람 추가했습니다.": "举报原因可用复选框多选。开发者模式下可查看举报人和被举报人的 ID 及举报内容（含最近聊天）。",
  "채팅창 상단에 '최근 활동' 표시합니다. 신고·차단 버튼을 점 3개 메뉴로 통합했습니다.": "聊天顶部 ID 下方显示“最近活动”。举报和拉黑按钮合并为三点菜单。",
  "채팅의 모든 요소(카드·알림 포함)에 반응 가능 추가했습니다. 더블클릭하면 하트 반응 추가했습니다. 반응 이모지를 말풍선에 붙여 표시합니다.": "聊天中的所有元素（包括卡片和通知）都可以回应。双击即可回应爱心。回应表情紧贴气泡显示。",
  "대국 신청 카드의 띄어쓰기 오류를 수정했습니다. '끝난 대국'을 '대국 종료됨'으로 표기합니다.": "修复对局邀请卡片的空格错误。“已结束的对局”改为“对局已结束”。",
  "미니게임 육각형 엠블럼에서 'MiniGame' 글자 삭제했습니다.": "删除小游戏六边形徽标上的“MiniGame”文字。",
  "신고 사유 (중복 선택 가능)": "举报原因（可多选）",
  "신고한 메시지와 최근 대화는 검토를 위해 운영진에게 전달. 상대에게는 알리지 않음": "被举报的消息和最近的聊天会发送给运营团队审核。不会通知对方",
  "신고 목록": "举报列表",
  "새로 고침": "刷新",
  "처리 대기": "待处理",
  "처리 완료": "已处理",
  "서버에 반영되지 않음. supabase-setup.sql 재실행 필요": "服务器尚未更新。请重新运行 supabase-setup.sql",
  "불러오기 실패": "加载失败",
  "신고 없음": "暂无举报",
  "프로필 신고": "个人资料举报",
  "신고된 메시지": "被举报的消息",
  "대화 기록": "聊天记录",
  "대국 종료됨": "对局已结束",
  "대결 종료됨": "对战已结束",
  "최근 활동 : {0}": "最近活动：{0}",
  "분석 탭 수 블록의 공개 데이터 통계가 '- / -'로 남거나 채택률 막대가 비던 문제를 수정했습니다. 통계 조회가 실패하면 자동으로 다시 시도 추가했습니다.": "修复分析标签页着法块中 公开数据 统计一直显示“— / —”或采用率条为空的问题。统计请求失败时会自动重试。",
  "프로필의 통계 전환 버튼을 'OpenChess'·'외부 사이트' 글자로 변경했습니다.": "个人资料的统计切换按钮改为“OpenChess”“外部网站”文字。",
  "미니게임 랭킹 화면의 중복된 '로비' 버튼 삭제했습니다.": "删除小游戏排行榜界面中重复的“大厅”按钮。",
  "일반 대국 전적·레이팅·랭킹 추가했습니다. 랜덤 매칭 결과가 미니게임과 같은 형태의 랭킹에 반영했습니다.": "新增普通对局的战绩、等级分和排行榜。随机匹配的结果会计入与小游戏相同形式的排行榜。",
  "나이트 레이스 이동 수 제한 삭제했습니다. 제한시간 안이면 몇 수든 이동 가능 추가했습니다.": "取消马跳竞速的步数限制。时限内可以走任意多步。",
  "나이트 레이스 혼자 플레이에서 목표에 못 닿으면 정산 전에 최단 경로를 금색 화살표로 표시합니다.": "马跳竞速单人游戏中未能到达目标时，结算前会用金色箭头显示最短路径。",
  "나이트 레이스 거리 판정 연출이 칸에서 어긋나던 문제를 수정했습니다.": "修复马跳竞速距离判定动画与格子错位的问题。",
  "무한 체크메이트 포지션을 수천 개로 확대했습니다. 백랭크·스모더드 등 다양한 체크메이트 모양을 고르게 출제하며, 한 번 나온 포지션은 모두 소진하기 전까지 다시 나오지 않습니다.": "无限将杀的局面扩充到数千个。底线杀、闷杀等多种将杀形态均衡出现，已出现过的局面在全部用完之前不会重复。",
  "무한 체크메이트 대전에서 상대의 진행 상황(수순 탐색 중·정확한 수순·실패·체크메이트 성공) 표시합니다.": "无限将杀对战中显示对手的进度（寻找路线、路线正确、失败、将杀成功）。",
  "무한 체크메이트 동점 시 결과 화면 전에 등급별 성공 수를 하나씩 비교하는 정산 화면 추가했습니다.": "无限将杀出现平局时，结果前会先显示按等级逐项比较成功数的决胜画面。",
  "일반 대국 랭킹, 나이트 레이스 개선, 무한 체크메이트 대폭 확장, 공개 데이터 통계 표시 수정했습니다.": "普通对局排行榜，马跳竞速改进，无限将杀大幅扩充，修复 公开数据 统计显示。",
