  "백의 첫 수. e4·d4가 압도적. b4(폴란드)·f4(버드)처럼 평가가 떨어지는 수는 부정확으로 분류": "白方首着。e4 和 d4 占绝对多数。b4（波兰开局）、f4（伯德开局）等使评价下降的着法归为不精确着法",
  "킹 폰 오프닝. 중앙 점유, 비숍·퀸 길을 열어 빠른 전개와 공격": "王兵开局。占据中心，打开象和后的通道，以便快速出子和进攻",
  "퀸 폰 오프닝. e4보다 폐쇄적·전략적, 안정적인 중앙 장악": "后兵开局。比 e4 更封闭、更具战略性，稳健地控制中心",
  "이탈리안 게임. 비숍을 c4로 보내 f7 약점 공략. 흑 …Bc5(지우코 피아노) 또는 …Nf6(투 나이츠)": "意大利开局。象走到 c4 攻击 f7 弱点。黑方走 …Bc5（朱奥科·皮亚诺）或 …Nf6（双马防御）",
  "루이 로페즈(스패니시). 흑 c6 나이트를 압박해 e5 폰 수비를 흔듦. 가장 깊이 연구된 오프닝 중 하나": "西班牙开局（鲁伊·洛佩斯）。压迫黑方 c6 的马，动摇对 e5 兵的保护。是研究最深入的开局之一",
  "시칠리안 디펜스. 비대칭 구조로 반격. 최상위에서 가장 인기 있는 e4 대응": "西西里防御。以不对称结构反击。顶级水平中对 e4 最受欢迎的应对",
  "님조/퀸즈 인디언 계열 입구. 흑이 유연하게 중앙 통제": "尼姆佐/后翼印度体系的入口。黑方灵活地控制中心",
  "{0} 정석 이론대로 전개되는 라인": "按标准 {0} 理论展开的线路",
  "2...f6는 f7-킹 대각선을 약화시키고 나이트 출구를 막는 대표적인 악수. 백은 e5 폰을 희생해 바로 응징 가능": "2...f6 削弱 f7—王的斜线并堵住马的出路，是典型的坏着。白方可弃 e5 兵立即惩罚",
  "3.Nxe5! 나이트를 내주고 폰을 잡으며 f7-h5 대각선 공략": "3.Nxe5!弃马吃兵，攻击 f7—h5 斜线",
  "3...fxe5 받으면(거의 강제) e8-h5 대각선이 완전히 열림": "若接受 3...fxe5（几乎被迫），e8—h5 斜线将完全打开",
  "4.Qh5+ 더블 어택. 4...Ke7 5.Qxe5+로 룩까지 따내며 백 대승": "4.Qh5+ 是双重攻击。4...Ke7 5.Qxe5+ 连车也吃掉，白方大胜",
  "5...Nxd5?는 폰을 되찾지만 f7이 무방비. 백은 나이트를 희생하는 프라이드 리버로 응징": "5...Nxd5? 虽夺回兵，但 f7 无人防守。白方以弃马的煎肝攻击加以惩罚",
  "6.Nxf7! 나이트를 희생해 킹을 끌어냄": "6.Nxf7!弃马将王引出",
  "6...Kxf7 받으면 킹이 노출": "若接受 6...Kxf7，黑王暴露",
  "7.Qf3+ 킹과 d5 나이트를 동시에 공격. 백이 주도권": "7.Qf3+ 同时攻击王和 d5 的马。白方掌握主动",
