  "불러오기": "载入",
  "PGN은 검증 후 그 수순 그대로 분석 탭에서 이어 둘 수 있음. FEN은 그 포지션(차례·캐슬링 권리·앙파상 포함)부터 이어 두는 FEN 모드로 전환되고, 처음 두는 수가 1수로 표기됨": "PGN 经验证后，可在分析标签页中按原着法顺序继续走棋。FEN 会切换到 FEN 模式，从该局面（含行棋方、王车易位权和吃过路兵）继续，你走的第一步记为第 1 步",
