  "Tip: \"12.Nf3\"처럼 수 번호와 함께 적으면 해당 수로 이동하는 링크가 됨. 이어지는 수순으로 링크하려면 {0}처럼 대괄호 두 개 안에 수 번호와 수순을 공백으로 구분해 적기. 대괄호 안은 150자 제한에서 제외": "提示：像“12.Nf3”这样连同回合序号书写，即可成为跳转到该步的链接。若要链接到后续着法序列，请像 {0} 这样在双方括号内以空格分隔写出回合序号和着法。方括号内的文字不计入 150 字限制",
