  "체스판을 직접 두거나 PGN·FEN·chess.com 대국을 불러와 엔진 분석. 매 수의 정확도(최선/우수/실수/블런더 등급) 표시": "可自己在棋盘上走棋，也可载入 PGN、FEN 或 chess.com 对局进行引擎分析。每一步的准确度以评级显示（最佳/优秀/失误/严重失误等）",
  "오프닝 도감이란": "什么是开局图鉴",
  "체스 오프닝을 트리 구조로 정리한 지도. 학습 탭에서 오프닝을 실제로 두면 그 갈래가 도감에 해금, 도감에서 각 오프닝의 정통 수순과 유래 확인": "把国际象棋开局整理成树状结构的地图。在学习标签页实际走出某个开局，该分支就会在图鉴中解锁，可在图鉴中查看各开局的标准着法与来历",
  "사용하는 엔진": "使用的引擎",
  "Stockfish 계열 엔진 사용. 설정 탭에서 가볍고 빠른 기본 엔진, 더 강력한 Stockfish 17.1, 18 중 선택": "使用 Stockfish 系列引擎。可在设置中选择轻量快速的默认引擎，或更强的 Stockfish 17.1, 18",
  "퍼즐 생성 방식": "谜题的生成方式",
  "퍼즐 탭의 \"퍼즐 만들기\"에서 PGN·FEN 입력 또는 내 chess.com 대국 선택. 그 안의 실제 수(기물 희생·우위 점하기·실수 응징하기 등)로 직접 제작": "在谜题标签页的“制作谜题”中输入 PGN 或 FEN，或选择自己的 chess.com 对局，再用其中的实际着法（弃子、取得优势、惩罚对手失误等）亲自制作",
