  "퍼즐 만들기 마지막 단계 또는 이미 만든 퍼즐의 풀이 카드에서 언제든 공개/비공개 변경": "可在制作谜题的最后一步，或随时在已制作谜题的解题卡片中切换公开/不公开",
  "다른 사람의 퍼즐 풀기": "解其他人的谜题",
  "공개 퍼즐은 퍼즐 탭 목록에서 누구나 풀 수 있고, 좋아요·리포스트·공유 가능": "公开谜题任何人都可在谜题标签页列表中解答，并可点赞、转发、分享",
  "PLAY 페이지에서 타임 컨트롤을 고른 뒤 \"대국 상대 찾기\"로 랜덤 매칭, 또는 \"친구와 플레이하기\"에서 친구에게 도전장 발송": "在 PLAY 页面选好用时规则后，用“寻找对局对手”随机匹配，或在“与好友对弈”中向好友发送挑战",
  "채팅에서 대국 신청": "在聊天中发起对局",
  "친구와의 채팅창에 /play 명령어 입력. 예: \"/play 10\"은 10분 대국, \"/play 15+10\"은 15분에 매 수마다 10초씩 증가. 상대가 수락하면 바로 대국 시작": "在与好友的聊天框中输入 /play 命令。例如：“/play 10”为 10 分钟对局，“/play 15+10”为 15 分钟、每走一步加 10 秒。对方接受后立即开始对局",
