  "래피드·블리츠·불릿별 대국마다 오르내린 레이팅 표시": "按快棋、闪电战、超快棋分别显示每局对局的等级分升降",
  "오프닝별 승률 통계": "各开局胜率统计",
  "도감의 각 수마다 이 오프닝을 실전에서 얼마나, 어떻게 뒀는지 표시": "在图鉴的每一步上，显示你在实战中下这个开局的次数与情况",
  "CHESS.COM 연동": "CHESS.COM 关联",
  "실제로 둔 대국까지 분석": "连实战对局也一并分析",
  "설정 탭에서 chess.com 아이디만 연결하면 실전에서 둔 수만큼 도감이 해금되고 정확도·레이팅 변화 확인 가능": "只需在设置中关联 chess.com 用户名，图鉴就会按你实战下过的着法解锁，还能查看准确率与等级分变化",
  "손실 먼저 평균": "先平均损失",
  "(예전 방식)": "（旧方式）",
  "정확도 먼저 평균": "先平均准确率",
  "(현재 방식)": "（现方式）",
  "정확도 체계": "准确率体系",
  "정확도 계산 방식": "准确率的计算方式",
  "실수 횟수만 세지 않음. 게임 리뷰를 설계하며 거친 네 단계를 수식과 그래프로 소개": "并不只是数失误次数。用公式和图表介绍设计对局复盘时经历的四个阶段",
  "정확도 % 하나 뒤에 이런 계산이 있음": "一个准确率 % 的背后是这样的计算",
  "① 평가치(cp)를 승률로 변환": "① 将评价值（cp）转换为胜率",
  "엔진 평가치(centipawn)는 그대로 쓰면 불공평함. 이미 +500으로 크게 앞설 때 100점을 잃는 것과 0점 근처에서 100점을 잃는 것은 승부에 미치는 영향이 다름. 그래서 cp를 이 포지션에서 이길 확률(win%)로 변환. 로지스틱 곡선이라 0 근처에서는 가파르고 승부가 기운 구간에서는 완만함 {0}로 정의": "直接使用引擎评价值（厘兵）并不公平。在已领先 +500 时丢 100 分，与在 0 附近丢 100 分，对胜负的影响不同。因此把 cp 转换为该局面下的获胜概率（win%）。它是逻辑曲线，在 0 附近陡峭，在胜负已分的区间则平缓，定义为 {0}",
  "손실은 그 수 전후로 win%가 얼마나 떨어졌는지": "损失即该着前后 win% 下降了多少",
  "② 손실이 클수록 정확도는 더 가파르게 하락": "② 损失越大，准确率下降越陡",
  "정확도 = 103.17 × e^(−0.055 × 손실) − 3.17": "准确率 = 103.17 × e^（−0.055 × 损失） − 3.17",
  "이 승률% 손실을 지수 감쇠(exponential decay) 곡선에 넣어 수 하나의 정확도로 변환. 손실이 0에 가까우면 정확도는 100 근처, 손실이 커질수록 완만하지 않고 {0} 하락. 작은 실수는 관대하게, 큰 블런더는 냉정하게 반영": "把这个胜率% 损失代入指数衰减（exponential decay）曲线，转换成单步的准确率。损失接近 0 时准确率接近 100，损失越大则不是平缓下降，而是{0}下降。对小失误宽容，对严重失误则冷静地如实反映",
  "점점 더 가파르게": "越来越陡地",
  "③ 계산 순서를 잘못 잡았던 부분": "③ 计算顺序曾经出错的地方",
  "처음엔 손실을 먼저 평균 낸 뒤 그 평균 하나만 정확도로 변환. 감쇠 곡선이 아래로 볼록(convex)해서, {0}에 따라 이 순서는 각 수를 먼저 변환해 평균 내는 것보다 항상 같거나 높게 나옴. 무난한 수가 많을수록 블런더 한 번의 타격이 옅게 희석됨. 왼쪽 예시(무난한 수 9개 + 블런더 1개인 가상의 10수)에서 예전 방식은 {1}이 나오지만, chess.com처럼 각 수의 정확도를 먼저 구하고 {2}으로 모으면 {3}으로 평균 내면 블런더 하나가 체감되는 만큼 반영됨": "最初是先平均损失，再只把这一个平均值转换为准确率。由于衰减曲线向下凸（convex），根据{0}，这种顺序得到的结果总是大于或等于先转换每一步再取平均。稳妥的着法越多，一次严重失误的打击就被稀释得越淡。在左侧示例（假设的 10 步：9 步稳妥 + 1 个严重失误）中，旧方式得到 {1};而像 chess.com 那样先求出每一步的准确率，再用{2}汇总，得到 {3}，严重失误便能如实反映出它应有的分量",
  "옌센 부등식(Jensen's inequality)": "琴生不等式（Jensen's inequality）",
  "조화평균(harmonic mean)": "调和平均数（harmonic mean）",
  "④ 포지션에 따라 같은 실수의 무게가 다름": "④ 同样的失误在不同局面中分量不同",
  "배율 = 0.85 + 0.3 × Φ((날카로움 − 8) / 8)": "倍率 = 0.85 + 0.3 × Φ((尖锐度 − 8) / 8)",
  "정답이 하나뿐인 날카로운 포지션(엔진 후보 1·2·3위 평가가 크게 벌어짐)의 실수는 엄격하게, 후보가 비슷한 무난한 포지션의 실수는 관대하게 반영. 후보 평가의 표준편차(Φ는 정규분포 누적분포함수)를 0.85~1.15배 배율로 매핑해 손실에 곱함. 마지막으로 이 값을 진영별로 처음부터 지금까지 {0}내면, 게임이 길어질수록 수 하나의 영향이 옅어지면서도 블런더는 뚜렷하게 드러나는 최종 정확도가 나옴": "对于只有唯一正解的尖锐局面（引擎第 1、2、3 候选的评价相差很大）中的失误，判定从严；对于候选相近的平稳局面中的失误，判定从宽。把候选评价的标准差（Φ 为正态分布累积分布函数）映射为 0.85~1.15 倍的倍率，乘到损失上。最后对每一方从开局到当前的这些值取{0}，就得到最终准确率：对局越长，单步的影响越淡，而严重失误依然清晰可见",
  "조화평균": "调和平均数",
  "이 네 단계와 포지션 변동성 보정은 설정 탭의 리뷰 설정 카드에서 켜고 끌 수 있음": "这四个阶段和局面波动性校正可在设置的复盘设置卡片中开启或关闭",
