  "보안": "安全",
  "다국어 지원합니다. 설정 탭에서 English·日本語·中文(简体)·Español·हिन्दी 선택했습니다.": "支持多语言。可在设置标签页中选择 English、日本語、中文（简体）、Español、हिन्दी。",
  "체스 용어(체크메이트·앙파상·캐슬링 등)를 언어별 표준 용어로 번역 추가했습니다.": "国际象棋术语（将杀、吃过路兵、王车易位等）采用各语言的标准译法。",
  "날짜·숫자 표기가 선택한 언어에 맞춰 표시됩니다.": "日期和数字按所选语言的格式显示。",
  "레슨 본문·오프닝 설명 일부는 한국어로 표시됩니다. 순차 번역 예정 추가했습니다.": "部分课程正文和开局说明仍以韩语显示。将陆续翻译。",
  "설정 탭 정리했습니다. 계정·언어 카드를 맨 위로 이동, '통제 칸 표시'를 시각 효과로 통합했습니다.": "整理设置标签页。账户和语言卡片移至顶部，「显示被控制的格子」并入视觉效果。",
  "처음 접속하면 기기 언어로 자동 설정 추가했습니다. 직접 선택하면 그 언어로 고정했습니다.": "首次访问时按设备语言自动设置。手动选择后将固定为该语言。",
  "번역 화면의 복수형·대소문자·문장 연결 오류를 수정했습니다. 체스 용어 표기 전수 점검 추가했습니다.": "修正翻译界面中的复数、大小写和句子拼接错误。全面核对国际象棋术语。",
  "분석 탭 보드를 더 크게 표시합니다. 엔진 라인·평가치 막대도 같은 폭으로 확대했습니다.": "放大分析标签页的棋盘。引擎线路和评价条也同步加宽。",
  "수 블록의 공개 데이터 통계를 위쪽 블록부터 도착하는 대로 표시합니다.": "着法区块的 公开数据 统计从最上方的区块开始，到达即显示。",
  "수 블록의 키워드가 끝에서 되돌아오지 않고 같은 순서로 계속 흘러갑니다.": "着法区块的关键词不再在末端跳回，而是按同样顺序持续滚动。",
  "엔진 depth가 한 단계 깊어질 때마다 수 블록 평가치·정렬 갱신했습니다.": "引擎深度（depth）每加深一层，着法区块的评价值和排序就刷新一次。",
  "다국어 지원, 신고·차단 확대, 개인정보처리방침·이용약관, 분석 탭 개선, 앱 출시 준비 추가했습니다.": "多语言支持，举报与屏蔽扩展，隐私政策与服务条款，分析标签页改进，应用上架准备。",
  "5개 언어 선택, 체스 용어 표준 번역, 프로필 신고·차단, 개인정보처리방침·이용약관, 분석 탭 개선했습니다.": "5 种语言，国际象棋术语标准译法，资料页举报与屏蔽，隐私政策与服务条款，分析标签页改进",
  "5개 언어 선택, 체스 용어 표준 번역, 프로필 신고·차단, 개인정보처리방침·이용약관, 분석 탭 개선": "5 种语言，国际象棋术语标准译法，资料页举报与屏蔽，隐私政策与服务条款，分析标签页改进",
  "분석 탭 FEN 모드에서 평가치가 0.00으로 남고 엔진 라인이 비던 문제를 수정했습니다. 엔진 준비가 늦으면 이미 켜진 엔진으로 바로 분석했습니다.": "修复分析标签页 FEN 模式下评估值停在 0.00、不显示引擎线路的问题。引擎启动较慢时，改用已在运行的引擎立即开始分析。",
  "퍼즐 만들기에서 FEN 포지션의 '기물 희생하기'가 희생이 아닌 최선수를 정답으로 만들던 문제를 수정했습니다. 탁월한 수(희생)를 먼저 찾아 첫 수로 고정하고, 없으면 안내합니다.": "修复在谜题创建中，FEN 局面的“弃子”类型把非弃子的最佳着法当作答案的问题。现在会先找出精彩着法（弃子）并固定为第一步，找不到时给出提示。",
  "보드 편집 화면에 보드 뒤집기 버튼 추가했습니다.": "棋盘编辑界面新增翻转棋盘按钮。",
  "퍼즐 레이팅": "谜题等级分",
  "푼 퍼즐 {0}개": "已解 {0} 道谜题",
  "{0}% 완료": "已完成 {0}%",
  "총 대국": "总对局数",
  "타임 컨트롤별 레이팅": "按用时规则的等级分",
  "기록 없음": "暂无记录",
  "일반 대국 레이팅을 타임 컨트롤(불렛·블리츠·래피드·스탠다드)별로 분리했습니다. 타임 컨트롤 선택 화면의 분류 이름 옆에 레이팅 표시, 랭킹도 분류별 탭으로 구분 추가했습니다. 기존 일반 대국 레이팅은 초기화 추가했습니다.": "普通对局的等级分按用时规则（超快棋、闪电战、快棋、标准）分开计算。选择用时规则时，每个分类名称旁显示等级分，排行榜也按分类分页。原有的普通对局等级分已重置。",
  "/user 페이지의 XP·퍼즐 레이팅·레슨·총 대국 요약과 일반 대국(타임 컨트롤별)·미니게임 기록을 카드로 묶어 정리했습니다.": "整理 /user 页面：汇总 XP、谜题等级分、课程和总对局数，并把普通对局（按用时规则）与小游戏记录归入卡片。",
  "타임 컨트롤별 레이팅, /user 성취도 정리, FEN 모드 엔진 수정, 희생 퍼즐 첫 수 보정, 보드 편집 뒤집기 추가했습니다.": "按用时规则的等级分，/user 成就整理，FEN 模式引擎修复，弃子谜题首步修正，棋盘编辑翻转按钮。",
  "타임 컨트롤별 레이팅, /user 성취도, FEN 모드 엔진, 희생 퍼즐 추가했습니다.": "按用时规则的等级分，/user 成就，FEN 模式引擎，弃子谜题",
  "타임 컨트롤별 레이팅, /user 성취도, FEN 모드 엔진, 희생 퍼즐": "按用时规则的等级分，/user 成就，FEN 模式引擎，弃子谜题",
  "/user 페이지에서 미니게임 기록을 일반 대국보다 위에 표시합니다. 일반 대국에 외부 사이트 대국 통계와 같은 UI로 대국 기록(시간 규정·색 필터, 전체 기간 전적, 레이팅 그래프, 최근 대국 목록) 추가했습니다. 실시간 대국과 봇 대국 모두 포합니다.": "/user 页面中，小游戏记录现在显示在普通对局上方。普通对局卡片以与 外部网站 对局统计相同的界面显示对局记录（用时规则和颜色筛选、总战绩、等级分图表、最近对局），包含实时对局和与机器人的对局。",
  "봇과 둔 대국도 내 일반 대국 기록에 저장했습니다. 기록에 기간별 레이팅 변동 그래프 추가했습니다.": "与机器人的对局现在也会保存到普通对局记录，记录中新增等级分随时间变化的图表。",
  "채팅에서 이미 누른 하트를 다시 더블클릭하면 하트 해제했습니다.": "在聊天中对已点的爱心再次双击即可取消。",
  "나이트 레이스 보드 아래 색 범례 삭제했습니다.": "删除马跳竞速棋盘下方的颜色图例。",
  "모든 미니게임 상단 강화했습니다. 짙은 상단 바와 큰 뒤로가기 버튼, 큰 점수(30px)와 앞선 쪽 왕관 표시, 굵은 시간 막대, 큰 라운드 점, 내 수·상대 수·남은 시간을 담은 정보 줄 추가했습니다.": "强化所有小游戏的顶部：深色顶栏和更大的返回按钮、更大的分数（30px）并为领先方显示王冠、更粗的时间条、更大的回合圆点，以及显示己方步数、对手步数和剩余时间的信息条。",
  "한국어 외 모든 언어에서 글자 크기를 줄여, 번역 문구가 길어져도 화면이 일그러지지 않도록 보정했습니다.": "除韩语外的所有语言都缩小了字号，翻译文本变长时界面也不再变形。",
