  "마스터 대국 DB 선수": "大师对局库棋手",
  "FIDE 스탠다드 랭킹": "FIDE标准等级分排名",
  "FIDE 래피드 랭킹": "FIDE快棋等级分排名",
  "FIDE 블리츠 랭킹": "FIDE闪电战排名",
  "대진표": "对阵表",
  "마스터 대국 DB에 이 연도 대국 없음": "大师对局库中没有这一年的对局",
  "앱스토어 출시 준비 추가했습니다. 로그인을 시스템 브라우저로 처리하고 앱 링크로 돌아오도록 연결, 체스 엔진은 필요할 때 내려받도록 변경했습니다.": "应用商店上架准备：登录改用系统浏览器并通过应用链接返回，国际象棋引擎改为按需下载。",
  "모든 수의 등급(탁월·최선·실수 등)을 보드 위 효과로 표시합니다. 설정에서 모두, 탁월/유일만, 끔 중에서 선택했습니다.": "所有着法评级（精彩、最佳、失误等）以棋盘特效显示。可在设置中选择全部、仅精彩/唯一着法或关闭。",
  "도감에 '마스터' 탭 추가했습니다. 세계 챔피언 계보와 대회(우승자·마스터 대국 DB 집계·대표 대국), 회로도 모양의 마스터 트리, FIDE 스탠다드·래피드·블리츠 상위 100위 랭킹, 대국 DB 최고 레이팅 상위 900명 마스터 추가했습니다.": "図鉴新增“大师”标签：世界冠军谱系与赛事（冠军、大师对局库统计、精选对局）、电路图样式的大师树、FIDE 标准·快棋·闪电战前 100 名排名，以及对局库中最高等级分前 900 名大师。",
  "마스터 이름을 한글로 표기하고 국적을 국기 이모지로 표시합니다. 최고 레이팅 알약 왼쪽에 MAX 표시합니다.": "大师姓名以韩文显示，国籍以国旗表情符号显示。最高等级分标签左侧新增 MAX 标记。",
  "'외부로 공유' 화면을 모든 곳에서 같은 모양으로 통일했습니다.": "统一各处“对外分享”界面的外观。",
  "플레이 탭의 미니게임 이름·레이팅 배치를 정리하고, 일반 대국 카드에 레이팅 줄(배치를 마친 분류만)과 타임 컨트롤 분류별 레이팅 알약 추가했습니다. 상단의 '내 기록·래피드' 제목 삭제했습니다.": "整理对弈页签中小游戏名称与等级分的布局，并在普通对局卡片中新增等级分行（仅限已完成定级的分类）和按用时分类的等级分标签。删除顶部“我的记录·快棋”标题。",
  "오프닝 트리의 보이는 영역과 드래그 감도를 마스터 트리와 같게 통일하고, 마스터 트리에 확대·축소(100% 기준)와 모바일 두 손가락 확대 추가했습니다.": "开局树的可视区域与拖动灵敏度与大师树统一，大师树新增缩放（以 100% 为基准）和手机双指缩放。",
  "마스터 트리의 챔피언·랭킹·마스터 블록 디자인을 새로 다듬고 고급 서체로 교체했습니다. 가운데 칩에서 사방으로 전류가 흐르는 효과 추가했습니다.": "重新设计大师树中冠军、排名和大师方块，并换用高级字体，新增从中央芯片向四个方向流动的电流效果。",
  "탁월한 수 판정이 체크메이트가 걸린 상황에서 독이 든 희생을 통과시키던 문제를 수정했습니다.": "修复在涉及将杀的局面中，精彩着法判定误放行有毒弃子的问题。",
  "모바일에서 마스터 상세 카드가 잘려 보이던 문제를 수정했습니다.": "修复手机上大师详情卡片被裁切的问题。",
  "마스터 도감, 수 등급 보드 효과, 앱스토어 출시 준비, 탁월한 수 판정 보정했습니다.": "大师图鉴，着法评级特效，应用商店准备，精彩着法判定修复。",
  "마스터 도감, FIDE 상위 100위, 수 등급 효과, 앱스토어 준비 추가했습니다.": "大师图鉴，FIDE 前 100 名，着法评级特效，应用商店准备",
  "마스터 도감, FIDE 상위 100위, 수 등급 효과, 앱스토어 준비": "大师图鉴，FIDE 前 100 名，着法评级特效，应用商店准备",
  "계정 및 데이터 삭제 안내": "账号与数据删除说明",
  "1. 앱·웹에서 직접 삭제": "1. 在应用或网页上自行删除",
  "OpenChess에 로그인한 뒤 설정 탭에서 계정 센터 열기": "登录 OpenChess 后，在设置标签页中打开账号中心",
  "계정 센터 아래쪽의 \"계정 탈퇴\"를 누르고 아이디를 입력해 확인": "点击账号中心底部的“注销账号”，并输入用户名确认",
  "2. 삭제되는 데이터": "2. 会被删除的数据",
  "계정 정보(이메일, 로그인 수단 연결, 아이디, 닉네임, 회원 번호)와 프로필 사진·소개": "账号信息（邮箱、已关联的登录方式、用户名、昵称、会员编号）以及头像和简介",
  "학습 진도, 퍼즐 풀이 기록과 직접 만든 퍼즐, 대국·미니게임 기록과 레이팅": "学习进度、谜题解答记录和自己创建的谜题、对局与小游戏记录以及等级分",
  "친구 관계, 채팅 메시지, 알림, 신고·차단 내역": "好友关系、聊天消息、通知以及举报和屏蔽记录",
  "진행 중이던 대국은 기권 처리되어 상대에게 승리로 기록된 뒤 삭제": "进行中的对局会按认输处理，记为对手获胜，然后删除",
  "3. 삭제 후에도 남는 정보": "3. 删除后仍保留的信息",
  "상대의 통계에 이미 반영된 승패·레이팅 변동 수치는 남지만 탈퇴한 이용자를 알아볼 수 없음": "已计入对手统计的胜负和等级分变化数值会保留，但无法识别出已注销的用户",
