  "PGN은 검증 후 그 수순 그대로 분석 탭에서 이어 둘 수 있음. FEN은 그 포지션(차례·캐슬링 권리·앙파상 포함)부터 이어 두는 FEN 모드로 전환됨.": "PGN 验证后会按原手顺载入，可在分析标签页继续走棋。FEN 会切换到 FEN 模式，从该局面（含轮到谁走、王车易位权利、吃过路兵）继续走棋。",
  "구간 × 유형": "阶段 × 类型",
  "그만하기": "停止",
  "전체 {0}장, 익힌 카드 {1}장": "共{0}张，已掌握{1}张",
  "나와 닮은 마스터": "与你相似的大师",
  "{0}와(과) 기준별 비교": "与{0}的逐项对比",
  "비슷한 기준 {0}/{1}": "相似的项目 {0}/{1}",
  "성장 분석": "成长分析",
  "성장 분석을 새로 만들고, 유산을 게시물로 바꿨습니다. 플레이 퀘스트가 생기고 티어 승급과 티어 여정, 도감도 새 디자인이 됐습니다.": "重做了成长分析，并将遗产改为帖子。新增对局任务，段位晋升、段位之旅和图鉴也换上了新设计。",
  "성장 분석이 최근 대국 5판을 알아서 분석합니다.": "成长分析会自动分析你最近的5局。",
  "성장 분석을 새로 만들었습니다. 최근 대국 5판을 컴퓨터가 알아서 리뷰해 성장 요약, 약점 진단, 지금 고칠 한 가지, 실수 기록, 마스터 스타일로 보여 줍니다.": "重新制作了成长分析。电脑会自动复盘你最近的5局，并展示成长概览、弱点诊断、现在要改的一点、失误记录和大师风格。",
  "실수 기록은 한 수씩 블록으로 보여 줍니다. 승률이 얼마나 떨어졌는지, 왜 떨어졌는지, 대신 둘 수 있었던 수는 무엇인지 알려 줍니다.": "失误记录以一步一块的方式展示：胜率下降了多少、为什么下降，以及本可以走的着法。",
  "유산이 게시물이 됐습니다. 최대 200개까지 쌓이고, 좋아요와 리포스트, 친구에게 보내기를 할 수 있으며 한 줄 가로 스크롤로 넘겨 봅니다.": "遗产现在是帖子了。最多可保存200条，可以点赞、转发、发送给好友，并在一行横向滚动中浏览。",
  "유산에 공유 링크가 생겼습니다. openchess.kr/legacy/고유번호 주소로 로그인 없이 볼 수 있고, 남의 유산도 채팅으로 보낼 수 있습니다.": "遗产有了分享链接。无需登录即可通过 openchess.kr/legacy/编号 查看，也可以在聊天中发送他人的遗产。",
  "유산 재생기를 처음부터 다시 만들었습니다. 금색 액자가 그려지며 열리고, 유산 수 직전에 나머지 기물이 어두워지며 표적이 잡힌 뒤 도착하면 등급 배지가 튀어 오릅니다.": "遗产播放器从头重做。金色画框描绘出现，关键着法前其余棋子变暗并锁定目标，落子后评级徽章弹出。",
  "플레이 탭에 플레이 퀘스트가 생겼습니다. 일반 대국과 미니게임에서 조건을 달성하면 클리어되고, 한국 시간 자정에 새로 시작합니다.": "对局页新增了对局任务。在普通对局和小游戏中达成条件即可完成，韩国时间午夜重置。",
  "프로필 카드를 띄우던 곳은 모두 내 /user 페이지로 이어지고, 그 페이지의 설정(세로 점 세 개) 버튼에서 프로필을 편집합니다.": "所有原本弹出资料卡的地方现在都会跳转到我的 /user 页面，并通过该页面的设置（竖三点）按钮编辑资料。",
  "데스크톱의 검색, 프로필, 친구, 채팅 창에 확대 버튼을 넣었습니다. 누르면 화면 거의 전체 크기로 커집니다.": "桌面端的搜索、资料、好友、聊天窗口新增放大按钮，点击后几乎占满整个屏幕。",
  "티어 승급 연출을 처음부터 다시 만들었습니다. 원근 격자 무대에서 링이 차오르고 부서진 뒤, 새 기물이 내리꽂히며 이름이 글자마다 켜집니다.": "段位晋升演出从头重做。在透视网格舞台上光环充能并碎裂，新棋子落下，名称逐字点亮。",
  "티어 여정을 티어마다 한 장씩 쌓이는 연대기로 바꿨습니다. 티어마다 직접 그린 고유한 배경과 구간 사다리가 있고, 화면 크기에 맞춰 배치가 바뀝니다.": "段位之旅改为每个段位一章的编年式布局。每个段位都有专属绘制的背景和段位阶梯，并会随屏幕大小调整排版。",
  "도감 첫 화면의 카드 네 장을 테마마다 색과 무늬가 다른 포스터형으로 다시 디자인했습니다.": "图鉴首页的四张卡片重新设计为海报式，每个主题都有不同的颜色和图案。",
  "집중 분석 모드에 사이트 톤으로 직접 만든 스크롤바를 넣었습니다.": "专注分析模式加入了按站点风格自制的滚动条。",
  "학습 탭을 다듬었습니다. 최근 대국 박스는 시간 규정을 플레이 탭과 같은 표기로 보여 주고 흑백 필터가 생겼으며, 칭호는 이름 아래 한 줄로 따로 표시합니다.": "优化了学习页。最近对局卡片的用时显示与对局页一致，新增执黑执白筛选，称号单独显示在名字下方一行。",
  "빠른 리뷰 진입 연출을 다듬었습니다. 게이지가 찰 때마다 아래 이름이 글리치와 함께 바뀌고, 글자마다 비슷한 시간 동안 보입니다.": "优化了快速复盘的入场演出。每格进度条充满时，下方名称会伴随故障效果变化，每个字母的显示时间也大致相同。",
  "성장 요약 타일의 폰트와 정렬을 정리했습니다. 숫자가 칸 밖으로 넘쳐 옆 칸과 겹치던 문제를 없앴습니다.": "整理了成长概览卡片的字体和对齐，数字不再溢出到相邻卡片。",
  "모바일에서 빠른 리뷰를 쓰면 정확도가 나오는 화면으로 먼저 들어갑니다.": "在手机上使用快速复盘时，会先进入显示准确率的画面。",
  "모바일에서 플레이 탭도 게임과 퀘스트를 학습 탭과 같은 두 페이지 스와이프로 보여 줍니다. 탭 상단의 제목은 모두 없앴습니다.": "手机上的对局页也用与学习页相同的两页滑动展示对局和任务。各页顶部的标题已全部移除。",
  "/about 소개 페이지에서 다른 서비스 이름을 모두 지웠고, 모든 버전 설명과 업데이트 소식, 개발자 기록을 존댓말 문장으로 통일했습니다.": "已从 /about 介绍页删除所有其他服务名称，并将所有版本说明、更新消息和开发者记录统一为礼貌语气。",
  "집중 분석에서 마스터 통계에서 해설로 버튼을 눌러도 반쯤 넘어가다 멈추던 문제를 고쳤습니다.": "修复了专注分析中从大师统计点击解说按钮时只切换到一半就停住的问题。",
  "데스크톱의 검색, 프로필, 친구, 채팅 창 안에서 마우스 휠로 가로 스크롤이 안 되던 문제를 고쳤습니다.": "修复了桌面端搜索、资料、好友、聊天窗口内无法用鼠标滚轮横向滚动的问题。",
  "안드로이드 기기의 빠른 리뷰 화면에서 게이지와 이름이 OPEN 글자 위에 겹치던 문제를 고쳤습니다.": "修复了部分安卓设备快速复盘画面中进度条和名称与 OPEN 字样重叠的问题。",
  "최근 변화": "近期变化",
