  "학습 탭은 내 성장을 모아 둔 곳입니다.": "学习页是汇集你成长的地方。",
  "내 대국을 5판 이상 리뷰하면 열립니다. 모자랄 때는 게이지 바로 남은 판 수를 알려 줍니다.": "复盘自己的对局满5局后开启。不足时，进度条会显示还差几局。",
  "대국마다 오프닝, 전적, 탁월한 수와 유일한 수의 개수가 보입니다. 연두색 버튼으로 바로 리뷰할 수 있습니다.": "每局对局会显示开局、战绩，以及精彩和唯一着法的数量。点绿色按钮即可立即复盘。",
  "레슨은 갈래를 따라 순서대로 열리고, 오프닝 원칙부터 시작합니다.": "课程沿着分支依次解锁，从开局原则开始。",
  "리뷰한 대국이 {0}판 이상이면 성장 분석이 열림": "复盘{0}局以上后开启成长分析",
  "{0}판 더 리뷰하면 열림": "再复盘{0}局即可开启",
  "최근 대국의 연두색 리뷰 버튼으로 내 대국을 리뷰하면 한 판씩 쌓임": "用最近对局里的绿色复盘按钮复盘自己的对局，会逐局累积",
