  "많이 다름": "差别很大",
  "비교 불가": "无法比较",
  "차이": "差距",
  "판정 기준 — 비율 기준(오프닝 선택·캐슬링·퀸 교환·무승부)은 %p 차이로 {0}%p 이하 거의 같음, {1}%p 이하 비슷함, {2}%p 이하 다름, 그 이상 많이 다름. 빈도·길이 기준은 두 값의 배수로 판정하며 체크·기물 잡기는 {3}배, 대국 길이는 {4}배 이하면 거의 같음. 실력 비교가 아님": "等级判定方式：比例类项目（开局选择、王车易位、兑后、和棋）按百分点差距判定，{0}个百分点以内为几乎相同，{1}个以内为相似，{2}个以内为不同，更大则差别很大。频率与长度类项目按两个数值的倍数判定：将军和吃子在{3}倍以内、对局长度在{4}倍以内视为几乎相同。并非棋力比较",
  "마스터 이름으로 검색": "按名字搜索大师",
  "와(과) 기준별 비교": "与你的逐项对比",
  "일치도 {0}%": "相似度 {0}%",
  "학습 탭에 '성장 분석' 추가했습니다. 내 실수를 모아 보여 주는 약점 지도, 틀린 포지션을 간격을 두고 다시 푸는 복습 카드, 나와 닮은 마스터를 13가지 기준으로 비교하는 마스터 스타일 추가했습니다. 마스터 이름을 검색해 원하는 마스터와도 비교 추가했습니다.": "在学习标签页新增“成长分析”：汇总你失误的弱点地图、隔一段时间重做你做错局面的复习卡片，以及从13个维度比较你与大师的大师风格。还可以按名字搜索任意大师进行比较。",
  "게임 리뷰 공유에 '하이라이트 카드' 추가했습니다. 한 판에서 가장 극적인 수 3개를 보드 그림과 승률 흐름으로 한 장에 담습니다.": "在复盘分享中新增“精彩瞬间卡片”：把一盘棋最富戏剧性的3步棋，连同棋盘图和胜率走势放在一张图里。",
  "도감 오프닝 트리·마스터 트리와 퍼즐 모식도에 전체 화면 보기 추가했습니다. 왼쪽 위 버튼으로 켜고 끔 추가했습니다.": "为开局树、大师树和谜题示意图新增全屏查看。用左上角的按钮开关。",
  "스마트폰 뒤로가기 지원합니다. 화면을 한 단계씩 닫고 홈에서는 한 번 더 누르면 종료했습니다. 앱에서 외부 링크는 시스템 브라우저·메일 앱·외부 사이트 앱으로 열기 추가했습니다.": "支持智能手机返回键：逐级关闭界面，在首页再按一次即退出。在应用内，外部链接会用系统浏览器、邮件应用或 外部网站 应用打开。",
  "계정 및 데이터 삭제 안내 페이지(/account-deletion) 추가했습니다. 탈퇴하면 진행 중이던 대국은 기권 처리되고 내가 만든 퍼즐도 함께 삭제했습니다.": "新增账号与数据删除说明页面（/account-deletion）。注销账号时，进行中的对局会按认输处理，你创建的谜题也会一并删除。",
  "분석 탭 보드 위 버튼을 복사, 편집, 리뷰 순서로 정리하고 편집 버튼에 글자 추가했습니다. FEN/PGN 붙여넣기는 보드 편집 화면의 '불러오기'로 통합했습니다.": "把分析标签页棋盘上方的按钮整理为复制，编辑，复盘的顺序，并为编辑按钮加上文字。FEN/PGN 粘贴并入棋盘编辑界面的“载入”。",
  "보드 편집 화면을 새로 디자인했습니다. 보드 중심 배치, 도구·기물·차례·불러오기·FEN 카드 추가했습니다.": "重新设计棋盘编辑界面：以棋盘为中心，配有工具、棋子、轮到谁走、载入和 FEN 卡片。",
  "도감 마스터 이름을 모든 언어에서 영어로 통일했습니다.": "图鉴中的大师名字在所有语言下统一显示为英文。",
  "체크메이트 뒤 상대가 나가 끝나지 않은 대국이 새 매칭을 막던 문제를 수정했습니다. 결과 확정 요청이 실패하면 다시 시도 추가했습니다.": "修复将杀后对方离开导致对局未结束、进而阻碍新匹配的问题。结果确认请求失败时会重试。",
  "탈퇴한 계정이 만든 퍼즐에 작성자 아이디가 남던 문제를 수정했습니다.": "修复已注销账号创建的谜题上仍保留创建者用户名的问题。",
  "좁은 화면에서 프로필 카드 위쪽 아이디가 버튼과 겹치던 문제를 수정했습니다. 통계 토글은 왼쪽, 프로필 편집은 오른쪽 정렬했습니다.": "修复窄屏幕上个人资料卡片顶部的用户名与按钮重叠的问题。统计切换靠左，编辑资料靠右。",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 스마트폰 뒤로가기, 계정 삭제 정리했습니다.": "成长分析，精彩瞬间卡片，示意图全屏，智能手机返回键，账号注销清理。",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 계정 삭제 안내합니다.": "成长分析，精彩瞬间卡片，示意图全屏，账号删除说明",
  "성장 분석, 하이라이트 카드, 모식도 전체 화면, 계정 삭제 안내": "成长分析，精彩瞬间卡片，示意图全屏，账号删除说明",
