  "유리할 때는 기물을 바꿔가며 안정적으로 승리를 굳히는 게 좋습니다.": "占优时兑子巩固胜势",
  "지고 있을 때는 기물 교환을 피하는 게 좋지만, 이 교환은 불가피한 최선의 선택이었습니다.": "落后时最好避免兑换棋子，但这次兑换是不可避免的最佳选择。",
  "기물 교환은 원래 피해야 하는 상황이지만, 이 교환만큼은 어쩔 수 없는 최선이었습니다.": "这种情况本来应避免兑换棋子，但这一次兑换是无可奈何的最佳选择。",
  "지고 있는 상황에서도 이 교환은 최선으로 불가피했습니다.": "即使落后，这次兑子也是最佳",
  "지고 있을 때는 기물 교환을 피하는 게 좋지만, 이 교환은 좋은 선택이었습니다.": "落后时最好避免兑换棋子，但这次兑换是个好选择。",
  "원래는 피해야 할 기물 교환이지만, 이번엔 괜찮은 선택이었습니다.": "本来该避免的棋子兑换，但这次是个不错的选择。",
  "지고 있는 상황이라도 이 교환만큼은 나쁘지 않은 선택이었습니다.": "即使落后，这次兑子也不差",
  "유리한 상황이라도 목적 없는 기물 교환은 손해가 될 수 있습니다. 기물 교환은 목적을 갖고 해야 합니다.": "即使占优，没有目的的棋子兑换也可能吃亏，兑换棋子要有目的。",
  "이기고 있어도 이 교환은 아쉬운 선택이었습니다. 기물 교환에는 목적이 있어야 합니다.": "即使领先，这次兑换也有些可惜，兑换棋子需要有目的。",
  "유리한 상황을 단순화하려던 거라면, 이번 교환은 아쉬운 선택이었습니다.": "若想借兑子简化优势局面，这是个可惜的选择",
  "지고 있는 상황에서는 기물 교환을 피하는 게 좋은데, 이 교환은 아쉬운 선택이었습니다. 기물 교환은 목적을 갖고 해야 합니다.": "落后时最好避免兑换棋子，这次兑换有些可惜，兑换棋子要有目的。",
  "지고 있을 때 기물을 바꾸면 역전 기회도 함께 줄어들습니다. 이 교환은 아쉬운 선택이었습니다.": "落后时兑换棋子也会减少翻盘的机会，这次兑换有些可惜。",
