  "칭호 전면 개편했습니다. 오프닝 숙련·활동·대국/레이팅·희귀 4갈래 53계열 241개, 오프닝 칭호는 13종에서 27종으로 확대했습니다.": "称号全面改版：开局精通、活动、对局与等级分、稀有 4 个类别，53 个系列，共 241 个称号。开局称号从 13 种扩展到 27 种。",
  "도감의 칭호를 업적으로 변경했습니다. 새로 얻은 칭호는 업적 화면에서 처음 볼 때 달성 연출 재생, 칭호 획득 팝업은 삭제했습니다.": "收藏中的称号改为成就。新获得的称号在成就界面首次查看时播放达成动画，称号获得弹窗已移除。",
  "안 얻은 칭호는 해금 조건과 진척도 게이지 표시합니다. 얻은 칭호는 꾹 누르거나 왼쪽으로 밀면 표시합니다.": "未获得的称号显示解锁条件和进度条。已获得的称号长按或向左滑动即可查看。",
  "도감 구역별 주소 추가했습니다. /opening, /master, /achievement, /skin 추가했습니다. 도감 탭은 테마 카드 첫 화면에서 시작했습니다.": "收藏各栏目有了独立地址：/opening、/master、/achievement、/skin。收藏页从主题卡片界面开始。",
  "집중 분석을 데스크톱에서 2단으로 배치했습니다. 왼쪽에 보드와 수 정보, 오른쪽에 탐색·유저 통계·마스터 통계·해설 추가했습니다.": "桌面端的专注分析改为两栏：左侧为棋盘和着法信息，右侧为探索、用户统计、大师统计和解说。",
  "칭호의 계열·단계 이름은 오프닝 이름을 제외하고 선택한 언어로 표시합니다.": "称号的系列和等级名称以所选语言显示，开局名称除外。",
  "칭호 배너 재디자인했습니다. 오프닝은 국기·이니셜 엠블럼, 단계가 오를수록 윤곽 두께와 장식이 늘고 5단계는 체스판이 금빛으로 점멸 추가했습니다.": "称号横幅重新设计。开局使用国旗或字母组合徽章，等级越高轮廓越粗、装饰越多，5 级时棋盘格会泛起金光。",
  "도감 첫 화면을 테마 카드 목록으로 변경했습니다. 업적 화면은 왼쪽 갈래 목록과 오른쪽 배너, 모바일은 위쪽 가로 목록 추가했습니다.": "收藏首页改为主题卡片列表。成就界面左侧为系列列表、右侧为横幅，手机上系列列表移到顶部横向滑动。",
  "도감 각 페이지의 ‹ 버튼을 검색창 왼쪽에 배치하고 상단 테마 버튼 삭제했습니다.": "收藏各页的返回键移到搜索栏左侧，顶部的主题按钮已移除。",
  "데스크톱 검색·친구·채팅 창을 끌 때 내용이 창과 함께 움직이도록 개선했습니다.": "桌面端拖动搜索、好友、聊天窗口时，内容随窗口同步移动。",
  "팝업 닫기 버튼을 불투명 공통 스타일로 통일했습니다. 로그인 팝업 로고를 좌상단으로 옮기고 확대했습니다. 설정 하단 링크 사이 쉼표 삭제했습니다.": "弹窗关闭按钮统一为不透明样式。登录弹窗的标志放大并移到左上角，设置底部链接之间的逗号已删除。",
  "도감 탭에서 로그인·프로필 팝업이 검색창에 가려지던 문제를 수정했습니다.": "修复在收藏页中登录和个人资料弹窗被搜索栏遮挡的问题。",
  "칭호 전면 개편, 업적 화면, 도감 테마 카드, 집중 분석 2단 배치했습니다.": "称号改版为成就、收藏首页主题卡片、专注分析两栏布局。",
  "칭호 241개, 업적 화면, 도감 테마 카드 추가했습니다.": "241 个称号、成就界面、收藏主题卡片",
  "칭호 241개, 업적 화면, 도감 테마 카드": "241 个称号、成就界面、收藏主题卡片",
