  "정답과 평가가 비슷한 수가 있어 정답이 모호할 수 있음": "有些着法的评分与答案接近，答案可能不够明确",
  "정한 수까지의 오프닝을 도감에서 무작위로 뽑음": "从开局图鉴中随机抽取指定步数的开局",
  "정한 수까지의 오프닝을 도감에서 뽑는 룰렛 전송 (수를 비우면 고르는 창)": "发送从开局图鉴中抽取指定步数开局的轮盘（不填步数则打开选择窗口）",
  "최선의 수 퀴즈": "最佳着法测验",
  "퀴즈 만들기": "创建测验",
  "퀴즈 만들기: 입력한 PGN·FEN 포지션에서 최선의 수를 오지선다로 맞히기": "创建测验：在输入的 PGN/FEN 局面中，用选择题猜最佳着法",
  "퀴즈 보내기": "发送测验",
