  "🎰 오프닝 룰렛": "🎰 开局轮盘",
  "🧠 최선의 수 퀴즈": "🧠 最佳着法测验",
  "빠른 리뷰": "快速复盘",
  "Stockfish 19 Lite, depth 15로 고정. 연출 없이 분석이 끝나면 바로 리뷰 화면": "固定为 Stockfish 19 Lite、depth 15。不播放动画，分析完成后直接进入复盘界面",
  "빠른 리뷰 사용 중. 엔진과 리뷰 속도 고정": "快速复盘已开启，引擎和复盘速度已固定",
  "평균": "标准",
  "빠른 리뷰 분석 중": "正在为快速复盘分析",
