  "수 선택": "着法",
  "재생 범위": "回放范围",
  "기보를 붙여넣고 플레이한 진영 선택": "粘贴棋谱并选择你执的一方",
  "최근 chess.com 대국 목록에서 바로 선택": "直接从最近的 chess.com 对局中选择",
  "설정에서 chess.com 계정 연동 시 이용 가능": "在设置中关联 chess.com 账号后可用",
  "대국 분석 중": "正在分析对局",
