  "집중 분석 댓글 블록을 유튜브 댓글창처럼 바꿨습니다.": "专注分析的评论区改成了YouTube评论区的样式。",
  "집중 분석 전체 통계를 추천 대국과 최근 대국으로 나누고, 대국을 OpenChess 안에서 바로 보고 리뷰합니다.": "专注分析的总体统计分为推荐对局和最近对局，并可在OpenChess内直接查看和复盘。",
