  "플레이 탭의 미니게임과 일반 대국 화면을 데스크톱에 맞는 2단 배치로 바꾸고 더 세련되게 다듬었습니다.": "对战页的小游戏和普通对局画面改为适合桌面的双栏布局，设计更精致。",
  "소셜 탭 게시물의 체스보드를 키우고, 퍼즐, 유산, 대국마다 다른 배경을 씁니다.": "社交页帖子的棋盘变大了，谜题、遗产和对局使用不同的背景。",
